const uploaded = $('Load your supplier list').first().binary || {};
const keys = Object.keys(uploaded);

if (keys.length === 0) throw new Error('No file was uploaded, so there is nothing to send.');

return [{ json: { filename: uploaded[keys[0]].fileName || null }, binary: { data: uploaded[keys[0]] } }];

const REQUIRED = ['supplier_name', 'contact_email', 'internal_sku'];
const EMAIL = /^[^@\s]+@[^@\s.]+\.[^@\s]+$/;

function key(name) {
  return String(name || '').trim().toLowerCase().replace(/[\s.-]+/g, '_');
}

const rows = $input.all().map((entry) => {
  const row = {};
  for (const [name, value] of Object.entries(entry.json)) row[key(name)] = String(value === null || value === undefined ? '' : value).trim();
  return row;
});

const invite = [];
const rejected = [];
const seen = new Set();

rows.forEach((row, index) => {
  const line = index + 2;
  const problems = [];

  for (const name of REQUIRED) {
    if (row[name] === undefined || row[name] === '') problems.push(`no ${name.replace(/_/g, ' ')}`);
  }
  if (row.contact_email && !EMAIL.test(row.contact_email)) problems.push(`'${row.contact_email}' is not an email address`);

  const fingerprint = `${String(row.contact_email || '').toLowerCase()}|${String(row.internal_sku || '').toLowerCase()}`;
  if (problems.length === 0 && seen.has(fingerprint)) problems.push(`${row.internal_sku} appears more than once for ${row.contact_email}`);

  if (problems.length > 0) {
    rejected.push({ line, internal_sku: row.internal_sku || null, reason: problems.join('; ') });
    return;
  }

  seen.add(fingerprint);
  invite.push({
    line,
    supplier_name: row.supplier_name,
    contact_email: String(row.contact_email).toLowerCase(),
    internal_sku: row.internal_sku,
    description: row.description || '',
  });
});

if (invite.length === 0) {
  throw new Error(`Nothing in that file can be sent. ${rejected.map((r) => `line ${r.line}: ${r.reason}`).join(' | ')}`);
}

return invite.map((row) => ({ json: Object.assign({ rejected, invite_count: invite.length }, row) }));

const config = $('Configuration').first().json;

return $input.all().map((entry) => {
  const row = entry.json;

  const body = [
    `Hello ${row.supplier_name},`,
    '',
    `${config.company_name} needs a packaging declaration for this item:`,
    '',
    `Reference: ${row.internal_sku}`,
    row.description ? `Description: ${row.description}` : null,
    '',
    'Please fill in the short form below and attach your declaration of conformity. It takes a couple of minutes.',
    '',
    config.form_url,
    '',
    `Use ${row.internal_sku} as the reference on the form so we can match it up.`,
    '',
    config.disclaimer,
  ]
    .filter((line) => line !== null)
    .join('\n');

  return {
    json: {
      to: row.contact_email,
      subject: `Packaging declaration needed for ${row.internal_sku}`,
      body,
    },
  };
});

const checked = $('Check the list').first().json;
const sent = $input.all().length;

const lines = [
  `Sent: ${sent}`,
  checked.rejected.length > 0 ? `Rejected: ${checked.rejected.length}` : null,
]
  .filter((line) => line !== null)
  .concat(checked.rejected.map((r) => `  line ${r.line}${r.internal_sku ? ` (${r.internal_sku})` : ''}: ${r.reason}`));

return [{ json: { sent, rejected: checked.rejected, report: lines.join('\n') } }];

const uploaded = $('Supplier declaration form').first().binary || {};
const keys = Object.keys(uploaded);

if (keys.length === 0) {
  return [{ json: { attached: false }, binary: {} }];
}

return [
  {
    json: { attached: true, filename: uploaded[keys[0]].fileName || null },
    binary: { data: uploaded[keys[0]] },
  },
];

const FIELDS = ['signatory', 'declaration_date', 'primary_material', 'pfas_statement', 'bpa_statement'];

function extractJson(text) {
  const body = String(text === undefined || text === null ? '' : text).trim();
  const fenced = /```(?:json)?\s*([\s\S]*?)```/.exec(body);
  const candidate = fenced ? fenced[1] : body;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}

const answer = $input.first().json;
const parsed = extractJson(answer.output || answer.text || '');

if (!parsed) {
  return [{ json: { read: false, reason: 'the declaration could not be read', fields: {} } }];
}

const fields = {};
for (const name of FIELDS) {
  const entry = parsed[name];
  if (!entry || entry.value === null || entry.value === undefined || String(entry.value).trim() === '') continue;
  const raw = Number(entry.confidence);
  fields[name] = {
    value: String(entry.value).trim(),
    confidence: Number.isFinite(raw) ? Math.min(1, Math.max(0, raw)) : 0,
  };
}

return [{ json: { read: true, reason: null, fields } }];

const form = $('Supplier declaration form').first().json;
const reading = $('Parse what was read').first().json;
const config = $('Configuration').first().json;

const floor = Number(config.confidence_floor);

const typed = {
  internal_sku: form['Your reference for this item'] || form.internal_sku || '',
  description: form['What is it'] || form.description || '',
  primary_material: form['Main material'] || form.primary_material || '',
  food_contact: String(form['Does it touch food'] || form.food_contact || '').toLowerCase() === 'yes',
  declaration_date: form['Date on the declaration'] || form.declaration_date || '',
  signatory: form['Who signed it'] || form.signatory || '',
};

const merged = {};
const marks = {};
const conflicts = [];

for (const name of ['signatory', 'declaration_date', 'primary_material']) {
  const own = String(typed[name] || '').trim();
  const found = reading.fields[name];

  if (own !== '') {
    merged[name] = own;
    marks[name] = 'supplier';
    if (found && found.confidence >= floor && found.value.toLowerCase() !== own.toLowerCase()) {
      marks[name] = 'conflict';
      conflicts.push({ field: name, typed: own, document: found.value });
    }
    continue;
  }

  if (found && found.confidence >= floor) {
    merged[name] = found.value;
    marks[name] = 'document';
    continue;
  }

  merged[name] = '';
  marks[name] = found ? 'unconfirmed' : 'missing';
}

for (const name of ['pfas_statement', 'bpa_statement']) {
  const found = reading.fields[name];
  merged[name] = found && found.confidence >= floor ? found.value : '';
  marks[name] = found ? (found.confidence >= floor ? 'document' : 'unconfirmed') : 'missing';
}

return [
  {
    json: {
      internal_sku: typed.internal_sku,
      description: typed.description,
      food_contact: typed.food_contact,
      contact_email: form['Your email address'] || form.contact_email || '',
      supplier_name: form['Your company'] || form.supplier_name || '',
      attached: $('Find the attachment').first().json.attached === true,
      document_read: reading.read === true,
      fields: merged,
      marks,
      conflicts,
    },
  },
];

const CHECKS = [
  {
    id: 'DOC-001',
    severity: 'blocker',
    message: 'No declaration was attached.',
    run: (s) => (s.attached ? 'pass' : 'fail'),
  },
  {
    id: 'DOC-002',
    severity: 'blocker',
    message:
      'The attached file could not be read. Send it as a text PDF rather than a photograph, or type the details into the form.',
    run: (s) => (!s.attached ? 'skip' : s.document_read ? 'pass' : 'fail'),
  },
  {
    id: 'SIG-010',
    severity: 'blocker',
    message: 'The declaration needs a named signatory.',
    run: (s) => (s.fields.signatory ? 'pass' : 'fail'),
  },
  {
    id: 'SIG-011',
    severity: 'blocker',
    message: 'The name you typed and the name on the document are different. Confirm which one is right.',
    run: (s) => (s.conflicts.some((c) => c.field === 'signatory') ? 'fail' : 'pass'),
  },
  {
    id: 'DATE-020',
    severity: 'blocker',
    message: 'The declaration needs a date.',
    run: (s) => (s.fields.declaration_date ? 'pass' : 'fail'),
  },
  {
    id: 'DATE-021',
    severity: 'blocker',
    message: 'The declaration is older than we can accept. Send a current one.',
    run: (s, config) => {
      const iso = /^\d{4}-\d{2}-\d{2}$/.exec(String(s.fields.declaration_date || '').trim());
      if (!iso) return 'skip';
      const age = (Date.parse(config.today) - Date.parse(iso[0])) / 86400000;
      return age <= Number(config.declaration_max_age_days) ? 'pass' : 'fail';
    },
  },
  {
    id: 'MAT-030',
    severity: 'blocker',
    message: 'The main material is missing.',
    run: (s) => (s.fields.primary_material ? 'pass' : 'fail'),
  },
  {
    id: 'PFAS-040',
    severity: 'blocker',
    message: 'This item touches food, so the declaration has to say whether PFAS were intentionally added.',
    run: (s) => (!s.food_contact ? 'skip' : s.fields.pfas_statement ? 'pass' : 'fail'),
  },
  {
    id: 'BPA-050',
    severity: 'blocker',
    message: 'This is plastic and touches food, so the declaration has to cover bisphenol A.',
    run: (s) => {
      const plastic = /plast|pet\b|pp\b|pe\b|ps\b|pvc/i.test(s.fields.primary_material || '');
      if (!s.food_contact || !plastic) return 'skip';
      return s.fields.bpa_statement ? 'pass' : 'fail';
    },
  },
  {
    id: 'DESC-060',
    severity: 'advisory',
    message: 'A short description helps us file this against the right item.',
    run: (s) => (String(s.description || '').trim().length >= 3 ? 'pass' : 'fail'),
  },
];

const submission = $input.first().json;
const config = $('Configuration').first().json;

const findings = [];
for (const check of CHECKS) {
  const status = check.run(submission, config);
  if (status === 'skip') continue;
  findings.push({ check_id: check.id, severity: check.severity, status, message: check.message });
}

const outstanding = findings.filter((f) => f.status === 'fail');
const blocking = outstanding.filter((f) => f.severity === 'blocker');

return [
  {
    json: {
      submission,
      findings,
      outstanding,
      complete: blocking.length === 0,
      checked_at: config.today,
      checklist_version: config.checklist_version,
      outstanding_text: outstanding
        .map((f) => `- ${f.severity === 'blocker' ? 'Required' : 'Note'}: ${f.message} [${f.check_id}]`)
        .join('\n'),
    },
  },
];

const verdict = $('Run the checklist').first().json;
const config = $('Configuration').first().json;

const body = [
  `Item: ${verdict.submission.internal_sku}`,
  verdict.submission.description ? `Description: ${verdict.submission.description}` : null,
  '',
  'Thank you. Your declaration is complete against the checks we run and we do not need anything further for this item.',
  '',
  config.disclaimer,
]
  .filter((line) => line !== null)
  .join('\n');

return [
  {
    json: {
      to: verdict.submission.contact_email,
      subject: 'Packaging declaration received and complete',
      body,
      complete: true,
      outstanding: 0,
    },
  },
];

