const verdict = $('Run the checklist').first().json;
const config = $('Configuration').first().json;
const drafted = String($input.first().json.output || $input.first().json.text || '').trim();

const allowed = new Set(verdict.outstanding.map((f) => f.check_id));
const prefixes = new Set(verdict.findings.map((f) => String(f.check_id).split('-')[0]));
const reference = String(verdict.submission.internal_sku || '').toUpperCase();

const mentioned = (drafted.match(/\b[A-Z]{2,8}-\d{2,4}\b/g) || []).filter(
  (id) => id.toUpperCase() !== reference && prefixes.has(id.split('-')[0])
);
const invented = [...new Set(mentioned.filter((id) => !allowed.has(id)))];
if (invented.length > 0) {
  throw new Error(`The drafted paragraph refers to ${invented.join(', ')}, which is not in this notice.`);
}

const cover =
  drafted !== ''
    ? drafted
    : 'We have looked at the declaration you sent and some of it is not complete yet. The points below are what we still need.';

const body = [
  `Item: ${verdict.submission.internal_sku}`,
  verdict.submission.description ? `Description: ${verdict.submission.description}` : null,
  '',
  cover,
  '',
  verdict.outstanding_text,
  '',
  'Send it again once you have those, using the same form:',
  '',
  config.form_url,
  '',
  `Use ${verdict.submission.internal_sku} as the reference again so we can match it up.`,
  '',
  config.disclaimer,
]
  .filter((line) => line !== null)
  .join('\n');

return [
  {
    json: {
      to: verdict.submission.contact_email,
      subject: `Packaging declaration: ${verdict.outstanding.length} point${
        verdict.outstanding.length === 1 ? '' : 's'
      } outstanding`,
      body,
      complete: false,
      outstanding: verdict.outstanding.length,
    },
  },
];
